// Browser-side output of a filled HTML template: print (the browser's own PDF engine, exact @page size, backgrounds
// on) and PDF download (each page rasterised at high resolution into a PDF of the template's exact page size).

// A hidden, same-origin frame holding the finished document. The document is generated by us from data we escape,
// and it carries a Content-Security-Policy that forbids any network access, so it cannot reach out.
function hiddenFrame(html: string): Promise<HTMLIFrameElement> {
  return new Promise((resolve, reject) => {
    const iframe = document.createElement('iframe');
    iframe.setAttribute('aria-hidden', 'true');
    iframe.style.cssText = 'position:fixed;left:-10000px;top:0;width:1200px;height:900px;border:0;visibility:hidden';
    iframe.onload = () => resolve(iframe);
    iframe.onerror = () => reject(new Error('Could not prepare the report card for printing'));
    iframe.srcdoc = html;
    document.body.appendChild(iframe);
  });
}

export async function printHtmlDocument(html: string): Promise<void> {
  const iframe = await hiddenFrame(html);
  const win = iframe.contentWindow;
  if (!win) { iframe.remove(); throw new Error('Print frame unavailable'); }
  // images are inline data URLs, but let layout settle (fit script, fonts) before the dialog opens
  await new Promise(r => setTimeout(r, 300));
  const cleanup = () => setTimeout(() => iframe.remove(), 500);
  win.addEventListener('afterprint', cleanup);
  win.focus();
  win.print();
  setTimeout(cleanup, 60_000); // some browsers never fire afterprint
}

// Each page of the filled document becomes one PDF page of exactly the template's size.
export async function buildPdfFromHtml(html: string): Promise<Blob> {
  const iframe = await hiddenFrame(html);
  try {
    const doc = iframe.contentDocument;
    if (!doc) throw new Error('Frame unavailable');
    await new Promise(r => setTimeout(r, 300));
    const pages = Array.from(doc.querySelectorAll<HTMLElement>('.rc-page'));
    if (!pages.length) throw new Error('Nothing to export');
    const [{ default: html2canvas }, { jsPDF }] = await Promise.all([import('html2canvas'), import('jspdf')]);
    let pdf: InstanceType<typeof jsPDF> | null = null;
    for (const el of pages) {
      const wPt = parseFloat(el.style.width), hPt = parseFloat(el.style.height);
      const canvas = await html2canvas(el, { scale: 2.5, backgroundColor: '#ffffff', useCORS: false, logging: false, windowWidth: Math.ceil(wPt * 4 / 3) + 40 });
      const orientation = wPt > hPt ? 'landscape' : 'portrait';
      if (!pdf) pdf = new jsPDF({ orientation, unit: 'pt', format: [wPt, hPt], compress: true });
      else pdf.addPage([wPt, hPt], orientation);
      pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, wPt, hPt);
    }
    return pdf!.output('blob');
  } finally {
    iframe.remove();
  }
}

export async function downloadHtmlAsPdf(html: string, fileName: string): Promise<void> {
  const blob = await buildPdfFromHtml(html);
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: fileName });
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}
